body.query:
query AliasHandling($alias: String!) {
  resource(alias: $alias) {
    ...ResourceRedirectDetails
  }
}

fragment ResourceRedirectDetails on Resource {
  __typename
  ... on Article {
    id
    title
    urlAlias
  }
  ... on Composition {
    id
    maybeTitle: title
    urlAlias
  }
  ... on DataUse {
    id
    title
  }
  ... on Document {
    id
    title
  }
  ... on MeetingEvent {
    id
    title
  }
  ... on News {
    id
    title
  }
  ... on Programme {
    id
    title
  }
  ... on GbifProject {
    id
    title
  }
  ... on Tool {
    id
    title
  }
}
